def test_registration_hashes_password_and_sets_session_cookie(
    client: TestClient,
) -> None:
    """Registration persists a hash and establishes a protected session."""
    response = client.post(
        "/api/auth/register",
        json={"username": "  TestPlayer  ", "password": "correct-horse"},
    )

    assert response.status_code == 201
    assert response.json() == {"id": 1, "username": "TestPlayer"}
    assert response.headers["cache-control"] == "no-store"
    set_cookie = response.headers["set-cookie"]
    assert "HttpOnly" in set_cookie
    assert "SameSite=lax" in set_cookie
    assert "Max-Age=2592000" in set_cookie
    assert "Secure" not in set_cookie

    with TestSession() as database:
        account = database.scalar(select(Account))
        assert account is not None
        assert account.password_hash != "correct-horse"
        assert account.password_hash.startswith("$argon2")
        assert password_hash.verify("correct-horse", account.password_hash)


def test_current_account_is_restored_from_session(client: TestClient) -> None:
    """A valid registration cookie resolves to the persisted Account."""
    registered = client.post(
        "/api/auth/register",
        json={"username": "PersistentPlayer", "password": "valid-password"},
    )

    response = client.get("/api/auth/me")

    assert registered.status_code == 201
    assert response.status_code == 200
    assert response.json() == registered.json()
    assert response.headers["cache-control"] == "no-store"


def test_login_accepts_case_insensitive_username_and_sets_session(
    client: TestClient,
) -> None:
    """Valid credentials restore the Account using its display-case username."""
    registered = client.post(
        "/api/auth/register",
        json={"username": "KnownPlayer", "password": "valid-password"},
    )
    client.cookies.clear()

    login = client.post(
        "/api/auth/login",
        json={"username": "  knownplayer  ", "password": "valid-password"},
    )
    current = client.get("/api/auth/me")

    assert registered.status_code == 201
    assert login.status_code == 200
    assert login.json() == registered.json()
    assert login.headers["cache-control"] == "no-store"
    assert "HttpOnly" in login.headers["set-cookie"]
    assert current.status_code == 200
    assert current.json() == registered.json()


