def test_logout_clears_session_cookie(client: TestClient) -> None:
    """Signing out invalidates the browser session without deleting the Account."""
    registered = client.post(
        "/api/auth/register",
        json={"username": "SigningOut", "password": "valid-password"},
    )

    logout = client.post("/api/auth/logout")
    current = client.get("/api/auth/me")

    assert registered.status_code == 201
    assert logout.status_code == 200
    assert logout.json() == {"status": "signed_out"}
    assert logout.headers["cache-control"] == "no-store"
    assert f'{SESSION_COOKIE_NAME}=""' in logout.headers["set-cookie"]
    assert "Max-Age=0" in logout.headers["set-cookie"]
    assert current.status_code == 401
    with TestSession() as database:
        assert database.scalar(select(Account).where(Account.username == "SigningOut"))


def test_current_account_rejects_missing_and_tampered_sessions(
    client: TestClient,
) -> None:
    """Missing or invalid signatures never authenticate an Account."""
    missing = client.get("/api/auth/me")
    client.cookies.set(SESSION_COOKIE_NAME, "tampered-token")
    tampered = client.get("/api/auth/me")

    assert missing.status_code == 401
    assert missing.json() == {"detail": "Not authenticated"}
    assert missing.headers["cache-control"] == "no-store"
    assert tampered.status_code == 401
    assert tampered.json() == {"detail": "Not authenticated"}
    assert tampered.headers["cache-control"] == "no-store"


def test_username_uniqueness_is_case_insensitive(client: TestClient) -> None:
    """Username comparisons reject duplicates regardless of display case."""
    first = client.post(
        "/api/auth/register",
        json={"username": "HamburgFan", "password": "valid-password"},
    )
    duplicate = client.post(
        "/api/auth/register",
        json={"username": "hamburgfan", "password": "another-password"},
    )

    assert first.status_code == 201
    assert duplicate.status_code == 409
    assert duplicate.json() == {"detail": "Username is already registered"}


def test_uniqueness_conflict_rolls_back_session(
    client: TestClient, monkeypatch: pytest.MonkeyPatch
) -> None:
    """A concurrent-style unique conflict rolls back before later requests."""
    first = client.post(
        "/api/auth/register",
        json={"username": "Concurrent", "password": "valid-password"},
    )
    monkeypatch.setattr(Session, "scalar", lambda *_args, **_kwargs: None)
    conflict = client.post(
        "/api/auth/register",
        json={"username": "CONCURRENT", "password": "another-password"},
    )

    assert first.status_code == 201
    assert conflict.status_code == 409


def test_registration_returns_prompt_service_unavailable_response(
    client: TestClient, monkeypatch: pytest.MonkeyPatch
) -> None:
    """Database connection failures return a sanitized retryable response."""

    def raise_connection_error(*_args: object, **_kwargs: object) -> None:
        """Simulate an unavailable database without contacting PostgreSQL."""
        raise OperationalError("SELECT account", {}, TimeoutError("unavailable"))

    monkeypatch.setattr(Session, "scalar", raise_connection_error)

    response = client.post(
        "/api/auth/register",
        json={"username": "Unavailable", "password": "valid-password"},
    )

    assert response.status_code == 503
    assert response.json() == {
        "detail": "Account service temporarily unavailable. Please try again."
    }
    assert response.headers["cache-control"] == "no-store"
    assert response.headers["retry-after"] == "5"


